STARTER_SOURCE = 'from __future__ import annotations\n\nimport asyncio\nimport threading\nfrom collections.abc import Awaitable, Callable\nfrom concurrent.futures import Future\nfrom contextvars import ContextVar, Token\nfrom dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass FlightInfo:\n    active: int\n    joined: int\n    total: int\n\n\nclass _FactoryContext:\n    def __init__(self, runner: object, key: object) -> None:\n        self.runner = runner\n        self.key = key\n        self.active = True\n\n\n_FACTORY_CONTEXTS: ContextVar[tuple[_FactoryContext, ...]] = ContextVar(\n    "async_single_flight_factory_contexts",\n    default=(),\n)\n\n\nclass _CallState:\n    def __init__(self) -> None:\n        self.future: Future = Future()\n        self.observers = 0\n        self.owner_loop: asyncio.AbstractEventLoop | None = None\n        self.producer: asyncio.Task | None = None\n\n\nclass AsyncSingleFlight:\n    def __init__(self) -> None:\n        self._lock = threading.Lock()\n        self._states: dict[object, _CallState] = {}\n        self._stats = [0, 0, 0]\n\n    def _enter_factory(self, key: object) -> tuple[_FactoryContext, Token]:\n        context = _FactoryContext(self, key)\n        token = _FACTORY_CONTEXTS.set((*_FACTORY_CONTEXTS.get(), context))\n        return context, token\n\n    @staticmethod\n    def _leave_factory(context: _FactoryContext, token: Token) -> None:\n        _FACTORY_CONTEXTS.reset(token)\n\n    def _reject_reentry(self, key: object) -> None:\n        for context in reversed(_FACTORY_CONTEXTS.get()):\n            if context.active and context.runner is self and context.key == key:\n                raise RuntimeError("reentrant single-flight dependency")\n\n    def _acquire(self, key: object) -> tuple[bool, _CallState]:\n        hash(key)\n        self._reject_reentry(key)\n        with self._lock:\n            self._stats[2] += 1\n            state = self._states.get(key)\n            if state is not None:\n                state.observers += 1\n                self._stats[1] += 1\n                return False, state\n            state = _CallState()\n            state.observers = 1\n            self._states[key] = state\n            self._stats[0] += 1\n            return True, state\n\n    def _set_producer(\n        self,\n        state: _CallState,\n        loop: asyncio.AbstractEventLoop,\n        producer: asyncio.Task,\n    ) -> None:\n        with self._lock:\n            state.owner_loop = loop\n            state.producer = producer\n\n    def _finish(self, key: object, state: _CallState) -> None:\n        with self._lock:\n            if self._states.get(key) is state:\n                del self._states[key]\n                self._stats[0] -= 1\n\n    @staticmethod\n    def _cancel_task(task: asyncio.Task) -> None:\n        if not task.done():\n            task.cancel()\n\n    def _release_observer(self, key: object, state: _CallState) -> None:\n        cancellation: tuple[asyncio.AbstractEventLoop, asyncio.Task] | None = None\n        with self._lock:\n            state.observers -= 1\n            if state.observers == 0 and self._states.get(key) is state:\n                if state.owner_loop is not None and state.producer is not None:\n                    cancellation = (state.owner_loop, state.producer)\n        if cancellation is not None:\n            loop, task = cancellation\n            try:\n                loop.call_soon_threadsafe(self._cancel_task, task)\n            except RuntimeError:\n                pass\n\n    async def _produce_call(\n        self,\n        key: object,\n        state: _CallState,\n        factory: Callable[[], Awaitable[object]],\n    ) -> None:\n        result = None\n        error: BaseException | None = None\n        cancelled = False\n        context, context_token = self._enter_factory(key)\n        try:\n            result = await factory()\n        except asyncio.CancelledError:\n            cancelled = True\n        except BaseException as exc:\n            error = exc\n        finally:\n            self._leave_factory(context, context_token)\n            if cancelled:\n                state.future.cancel()\n            elif error is not None:\n                state.future.set_exception(error)\n            else:\n                state.future.set_result(result)\n            self._finish(key, state)\n\n    async def run(\n        self,\n        key: object,\n        factory: Callable[[], Awaitable[object]],\n    ) -> object:\n        leader, state = self._acquire(key)\n        if leader:\n            loop = asyncio.get_running_loop()\n            try:\n                producer = loop.create_task(self._produce_call(key, state, factory))\n            except BaseException as exc:\n                self._finish(key, state)\n                state.future.set_exception(exc)\n            else:\n                self._set_producer(state, loop, producer)\n\n        wrapped = asyncio.wrap_future(state.future)\n        try:\n            return await asyncio.shield(wrapped)\n        finally:\n            self._release_observer(key, state)\n\n    def info(self) -> FlightInfo:\n        with self._lock:\n            return FlightInfo(*self._stats)\n\n    def clear(self) -> None:\n        with self._lock:\n            if self._stats[0]:\n                raise RuntimeError("cannot clear while flights are active")\n            self._stats = [0, 0, 0]\n\n\n__all__ = ["AsyncSingleFlight", "FlightInfo"]\n'
